// swift-tools-version: 5.9
// Shum-Core, the Rust core every Shum client shares, for the iPhone.
// The framework is built by Shum-Core's scripts/build-ios.sh (also published
// as a Shum-Core release); Sources/ShumCore/shum_mobile.swift is generated by
// the same script for the same revision. Update both together.
import PackageDescription

let package = Package(
    name: "ShumCore",
    platforms: [.iOS(.v16)],
    products: [
        .library(name: "ShumCore", targets: ["ShumCore"])
    ],
    targets: [
        // Kept in the repository so builds need no network, Xcode Cloud
        // included; SHUM_CORE_REVISION names the Shum-Core commit.
        .binaryTarget(name: "ShumCoreFFI", path: "ShumCoreFFI.xcframework.zip"),
        .target(
            name: "ShumCore",
            dependencies: ["ShumCoreFFI"],
            path: "Sources/ShumCore",
            linkerSettings: [.linkedLibrary("z")]
        ),
    ]
)
